@namespace sv_ca3b2f9349074e56989c7dd8cd2dca17.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(company: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(title: e.Value?.ToString())" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(startDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.StartDate)" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => Update(endDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => HandleCurrentChanged((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(description: e.Value?.ToString())"></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntryModel Entry { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void Update(string? company = null, string? title = null, DateTime? startDate = null, DateTime? endDate = null, string? description = null)
    {
        var updated = Entry with
        {
            Company = company ?? Entry.Company,
            Title = title ?? Entry.Title,
            StartDate = startDate ?? Entry.StartDate,
            EndDate = endDate ?? Entry.EndDate,
            Description = description ?? Entry.Description
        };
        OnChanged.InvokeAsync(updated);
    }

    private void HandleCurrentChanged(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnChanged.InvokeAsync(updated);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

