@namespace sv_ca3b2f9349074e56989c7dd8cd2dca17.Components.Pages.Apply

<div class="reference-entry-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Entry.Name" @onchange="e => Update(name: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Entry.Relationship" @onchange="e => Update(relationship: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Entry.Email" @onchange="e => Update(email: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Entry.Phone" @onchange="e => Update(phone: e.Value?.ToString())" />
    </div>
</div>

@code {
    [Parameter] public ReferenceModel Entry { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }

    private void Update(string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        var updated = Entry with
        {
            Name = name ?? Entry.Name,
            Relationship = relationship ?? Entry.Relationship,
            Email = email ?? Entry.Email,
            Phone = phone ?? Entry.Phone
        };
        OnChanged.InvokeAsync(updated);
    }

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

