@namespace sv_ca3b2f9349074e56989c7dd8cd2dca17.Components.Pages.Apply

<div class="step-form">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <textarea class="cover-letter-textarea"
                  @bind="CoverLetterText"
                  @bind:event="oninput"
                  maxlength="@MaxLength"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count">@CoverLetterText.Length / @MaxLength characters</div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-error">@ValidationMessage</div>
    }

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string ValidationMessage = "";

    private async Task HandleNext()
    {
        ValidationMessage = "";

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ValidationMessage = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetterText);
    }
}

