arguments.file_text:
@page "/apply"
@using sv_ca3b2f9349074e56989c7dd8cd2dca17.Components.Pages.Apply
@using sv_ca3b2f9349074e56989c7dd8cd2dca17.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is:</p>
            <p class="application-id">@ApplicationId</p>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@CurrentStep"
                       CompletedSteps="@CompletedSteps"
                       StepNames="@StepNames"
                       OnStepClicked="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@PersonalFullName"
                                  Email="@PersonalEmail"
                                  Phone="@PersonalPhone"
                                  Address="@PersonalAddress"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="@WorkEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="@References"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetterText="@CoverLetterText"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep FullName="@PersonalFullName"
                            Email="@PersonalEmail"
                            Phone="@PersonalPhone"
                            Address="@PersonalAddress"
                            WorkEntries="@WorkEntries"
                            References="@References"
                            CoverLetter="@CoverLetterText"
                            OnEditStep="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    private int CurrentStep = 0;
    private HashSet<int> CompletedSteps = new();
    private bool IsSubmitted;
    private int ApplicationId;

    private List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    // Step 1 state
    private string PersonalFullName = "";
    private string PersonalEmail = "";
    private string PersonalPhone = "";
    private string PersonalAddress = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> WorkEntries = new()
    {
        new WorkEntryForm.WorkEntryModel()
    };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> References = new()
    {
        new ReferenceForm.ReferenceModel(),
        new ReferenceForm.ReferenceModel()
    };

    // Step 4 state
    private string CoverLetterText = "";

    private void GoToStep(int step)
    {
        CurrentStep = step;
    }

    private void GoBack()
    {
        if (CurrentStep > 0)
            CurrentStep--;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        PersonalFullName = data.FullName;
        PersonalEmail = data.Email;
        PersonalPhone = data.Phone;
        PersonalAddress = data.Address;
        CompletedSteps.Add(0);
        CurrentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        WorkEntries = entries;
        CompletedSteps.Add(1);
        CurrentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        References = refs;
        CompletedSteps.Add(2);
        CurrentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        CoverLetterText = text;
        CompletedSteps.Add(3);
        CurrentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var workHistory = new WorkHistory(WorkEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
        ).ToList());

        var references = References.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)
        ).ToList();

        var personal = new PersonalInfo(PersonalFullName, PersonalEmail, PersonalPhone, PersonalAddress);
        var application = new JobApplication(personal, workHistory, references, CoverLetterText);

        ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        CompletedSteps.Add(4);
        IsSubmitted = true;
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border-radius: 2rem;
    font-size: 0.875rem;
    transition: all 0.2s;
}

.step.active {
    background: #2563eb;
    color: white;
    font-weight: 600;
}

.step.completed {
    background: #d1fae5;
    color: #065f46;
    cursor: pointer;
}

.step.completed:hover {
    background: #a7f3d0;
}

.step.dimmed {
    background: #f3f4f6;
    color: #9ca3af;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 50%;
    font-size: 0.75rem;
    font-weight: 700;
}

.step.active .step-number {
    background: rgba(255,255,255,0.2);
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #d1d5db;
}

/* Form Styles */
.step-form {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 0.75rem;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.375rem;
    color: #374151;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.625rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.cover-letter-textarea {
    width: 100%;
    min-height: 250px;
    padding: 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    resize: vertical;
    box-sizing: border-box;
}

.cover-letter-textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.char-count {
    text-align: right;
    font-size: 0.8125rem;
    color: #6b7280;
    margin-top: 0.375rem;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: 400 !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

.btn-next, .btn-submit {
    background: #2563eb;
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-weight: 500;
    cursor: pointer;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #1d4ed8;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn-back {
