toolArgs.file_text:
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border-radius: 2rem;
    font-size: 0.875rem;
    transition: all 0.2s;
}

.step.active {
    background: #2563eb;
    color: white;
    font-weight: 600;
}

.step.completed {
    background: #d1fae5;
    color: #065f46;
    cursor: pointer;
}

.step.completed:hover {
    background: #a7f3d0;
}

.step.dimmed {
    background: #f3f4f6;
    color: #9ca3af;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 50%;
    font-size: 0.75rem;
    font-weight: 700;
}

.step.active .step-number {
    background: rgba(255,255,255,0.2);
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #d1d5db;
}

/* Form Styles */
.step-form {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 0.75rem;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.375rem;
    color: #374151;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.625rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.cover-letter-textarea {
    width: 100%;
    min-height: 250px;
    padding: 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    resize: vertical;
    box-sizing: border-box;
}

.cover-letter-textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.char-count {
    text-align: right;
    font-size: 0.8125rem;
    color: #6b7280;
    margin-top: 0.375rem;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: 400 !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

.btn-next, .btn-submit {
    background: #2563eb;
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-weight: 500;
    cursor: pointer;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #1d4ed8;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn-back {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.75rem 2rem;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    cursor: pointer;
}

.btn-back:hover {
    background: #f9fafb;
}

.btn-add {
    background: white;
    color: #2563eb;
    border: 1px dashed #2563eb;
    padding: 0.625rem 1.25rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    cursor: pointer;
    width: 100%;
    margin-top: 1rem;
}

.btn-add:hover {
    background: #eff6ff;
}

.btn-remove {
    background: none;
    border: none;
    color: #dc2626;
    font-size: 0.8125rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-edit {
    background: none;
    border: none;
    color: #2563eb;
    font-size: 0.8125rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
}

.btn-edit:hover {
    text-decoration: underline;
}

/* Work Entry */
